using Godot;
using System;
using System.Collections.Generic;
using MySimulator.Rebuild;
namespace MySim {
public partial class SeriesSetupPanel : CanvasLayer {
 public Action<RaceSeries> StartSeries;readonly List<int> selected=new List<int>();ItemList rounds;OptionButton tracks,cars;SpinBox laps;Label status;
 public override void _Ready(){Layer=60;var shade=new ColorRect {Theme=MySimTheme.Build(),Color=MySimTheme.Ink,AnchorRight=1,AnchorBottom=1};AddChild(shade);var panel=new PanelContainer {AnchorLeft=.08f,AnchorRight=.92f,AnchorTop=.04f,AnchorBottom=.96f};shade.AddChild(panel);var box=new VBoxContainer();box.AddThemeConstantOverride("separation",8);panel.AddChild(box);box.AddChild(new Label {Text="SINGLE PLAYER / RACE SERIES"});box.AddChild(new Label {Text="Add tracks in race order. Repeat a circuit if you want another round."});tracks=new OptionButton();foreach(string name in SourceRoutes.Names)tracks.AddItem(name);box.AddChild(tracks);AddButton(box,"ADD ROUND",()=>{if(selected.Count>=60){status.Text="Maximum60rounds";return;}selected.Add(tracks.Selected);Refresh();});rounds=new ItemList {SizeFlagsVertical=Control.SizeFlags.ExpandFill,CustomMinimumSize=new Vector2(0,110)};box.AddChild(rounds);var edit=new HBoxContainer();box.AddChild(edit);AddButton(edit,"MOVE UP",()=>Move(-1));AddButton(edit,"MOVE DOWN",()=>Move(1));AddButton(edit,"REMOVE",()=>{var items=rounds.GetSelectedItems();if(items.Length>0){selected.RemoveAt(items[0]);Refresh();}});cars=new OptionButton();foreach(string name in CarCatalog.Names)cars.AddItem(name);cars.Selected=Mathf.Clamp(Settings.Get("car",0),0,CarCatalog.Count-1);box.AddChild(cars);var lapRow=new HBoxContainer();lapRow.AddChild(new Label {Text="LAPS PER ROUND"});laps=new SpinBox {MinValue=1,MaxValue=20,Value=Settings.Get("laps",3)};lapRow.AddChild(laps);box.AddChild(lapRow);status=new Label();box.AddChild(status);var actions=new HBoxContainer();box.AddChild(actions);AddButton(actions,"SESSION OPTIONS",()=>AddChild(new RaceSettingsPanel {SessionLabel="RACE SERIES"}));AddButton(actions,"START SERIES",()=>{if(selected.Count==0){status.Text="Add at least one track.";return;}StartSeries?.Invoke(new RaceSeries(selected.ToArray(),cars.Selected,(int)laps.Value));QueueFree();});AddButton(actions,"BACK",QueueFree);}
 void AddButton(Node parent,string text,Action action){var button=new Button {Text=text,CustomMinimumSize=new Vector2(0,42)};button.Pressed+=()=>action();parent.AddChild(button);}
 void Refresh(){rounds.Clear();for(int i=0;i<selected.Count;i++)rounds.AddItem((i+1)+"  "+SourceRoutes.Names[selected[i]]);status.Text=selected.Count+" rounds selected";}
 void Move(int direction){var items=rounds.GetSelectedItems();if(items.Length==0)return;int i=items[0],next=i+direction;if(next<0||next>=selected.Count)return;(selected[i],selected[next])=(selected[next],selected[i]);Refresh();rounds.Select(next);}
}
}
